        # Treat as adjacency matrix
        matrix = adj
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if matrix[i][j]:
                    adj_list[i].append(j)
    else:
        # Treat as adjacency list
        adj_list = adj
        # Convert to matrix for quick lookup if needed
        matrix = [[0] * n for _ in range(n)]
        for u in range(n):
            for v in adj_list[u]:
                matrix[u][v] = 1
                matrix[v][u] = 1

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: compute degeneracy ordering (smallest-last)
    def degeneracy_order():
        if n == 0:
            return []
        degree = [len(adj_list[i]) for i in range(n)]
        used = [False] * n
        buckets = [[] for _ in range(n)]
        for v in range(n):
            if degree[v] < n:
                buckets[degree[v]].append(v)
        order = []
        for _ in range(n):
            # Find non-empty bucket with smallest degree
            d = 0
            while d < n and not buckets[d]:
                d += 1
            if d >= n:
                break
            v = buckets[d].pop()
            used[v] = True
            order.append(v)
            for u in adj_list[v]:
                if not used[u]:
                    if degree[u] > 0:
                        buckets[degree[u]].remove(u)
                        degree[u] -= 1
                        if degree[u] < n:
                            buckets[degree[u]].append(u)
        return order

    # DSATUR implementation
    def dsatur():
