                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)
            # Step 4: while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                max_common = -1
                min_deg_U = n  # for tie-break: min degree in G[U]
                for u in U:
                    common = 0
                    for w in adj_list[u]:
                        if w in W:
                            common += 1
                    if common > max_common:
                        max_common = common
                        best_u = u
                        min_deg_U = len([x for x in adj_list[u] if x in U])
