def dsatur_coloring(n, neighbors):
    if n == 0:
        return []
    colors = [-1] * n
    saturated = [set() for _ in range(n)]
    # Order by degree descending for initial tie-breaking
    order = list(range(n))
    order.sort(key=lambda x: len(neighbors[x]), reverse=True)
    for _ in range(n):
        # Select uncolored vertex with max saturation, tie-break by degree in uncolored subgraph, then order
        candidates = [v for v in range(n) if colors[v] == -1]
        if not candidates:
            break
        # Compute saturation degree
        sat_deg = [len(saturated[v]) for v in candidates]
        max_sat = max(sat_deg)
        max_sat_vertices = [v for v, sat in zip(candidates, sat_deg) if sat == max_sat]
        if len(max_sat_vertices) == 1:
            v = max_sat_vertices[0]
        else:
            # Tie-break by degree in uncolored subgraph
            uncolored_set = set(candidates)
            deg_uncolored = [len(neighbors[v] & uncolored_set) for v in max_sat_vertices]
            max_deg = max(deg_uncolored)
            max_deg_vertices = [v for v, deg in zip(max_sat_vertices, deg_uncolored) if deg == max_deg]
            if len(max_deg_vertices) == 1:
                v = max_deg_vertices[0]
            else:
                # Break tie by order in initial degree ordering
                v = min(max_deg_vertices, key=lambda x: order.index(x))
        # Assign smallest available color
        used = {colors[u] for u in neighbors[v] if colors[u] != -1}
        c = 0
        while c in used:
            c += 1
        colors[v] = c
        # Update saturation of neighbors
        for u in neighbors[v]:
            if colors[u] == -1:
                saturated[u].add(c)
    return colors

def rlf_coloring(n, neighbors):
    if n == 0:
        return []
    colors = [-1] * n
    color = 0
    uncolored = set(range(n))
    while uncolored:
        # Build maximal independent set for this color
        # Choose vertex with max degree in uncolored subgraph
        if not uncolored:
            break
        v = max(uncolored, key=lambda x: len(neighbors[x] & uncolored))
        independent_set = {v}
        # Partition remaining uncolored into U (not adjacent to any in S) and W (adjacent to S)
        U = uncolored - {v} - (neighbors[v] & uncolored)
        W = (neighbors[v] & uncolored)
        # While U not empty, select vertex with max neighbors in W
        while U:
            # Select u in U maximizing |N(u) ∩ W|
            best_u = None
            best_score = -1
            for u in U:
                score = len(neighbors[u] & W)
                if score > best_score or (score == best_score and (best_u is None or u < best_u)):
                    best_score = score
                    best_u = u
            if best_u is None:
                break  # Should not happen
            independent_set.add(best_u)
            # Move best_u from U to independent set
            U.remove(best_u)
            # Move neighbors of best_u that are in U to W
            nbrs_in_U = neighbors[best_u] & U
            W.update(nbrs_in_U)
            U -= nbrs_in_U
        # Assign color to all in independent_set
        for v in independent_set:
            colors[v] = color
        # Remove independent_set from uncolored
        uncolored -= independent_set
        color += 1
    return colors

def smallest_last_ordering(n, neighbors):
    if n == 0:
        return []
    # Copy of degrees
    degrees = [len(neighbors[i]) for i in range(n)]
    removed = [False] * n
    order = []
    # We'll maintain a list of vertices sorted by current degree
    # Since n <= 100, we can recompute min each time
    for _ in range(n):
        # Find vertex with minimum degree among non-removed
        min_deg = float('inf')
        min_v = -1
        for v in range(n):
            if not removed[v]:
                if degrees[v] < min_deg:
                    min_deg = degrees[v]
                    min_v = v
        if min_v == -1:
            break  # Should not happen
        order.append(min_v)
        removed[min_v] = True
        # Decrease degree of neighbors
        for u in neighbors[min_v]:
            if not removed[u]:
                degrees[u] -= 1
    # Return reverse order for coloring
    return order[::-1]

def welsh_powell_ordering(n, neighbors):
    if n == 0:
        return []
    # Sort by degree descending
    order = list(range(n))
    order.sort(key=lambda x: len(neighbors[x]), reverse=True)
    return order

def greedy_coloring_from_order(n, neighbors, order):
    if n == 0:
        return []
    colors = [-1] * n
    for v in order:
        used = {colors[u] for u in neighbors[v] if colors[u] != -1}
        c = 0
        while c in used:
            c += 1
        colors[v] = c
    return colors

def kempe_refine(n, neighbors, colors, k):
    if k <= 1:
        return colors, k
    # Try to eliminate color classes from highest to lowest
    improved = True
    while improved:
        improved = False
        # Work on a copy
        cur_colors = colors[:]
        # Try to eliminate each color class starting from the highest
        for target_color in range(k-1, -1, -1):
            # Get vertices with this color
            vertices = [v for v in range(n) if cur_colors[v] == target_color]
            if not vertices:
                continue
            # Try to recolor each vertex to a lower color if possible
            for v in vertices:
                # Try direct reassignment to any lower color
                neighbor_colors = {cur_colors[u] for u in neighbors[v] if cur_colors[u] != -1}
                for c in range(target_color):
                    if c not in neighbor_colors:
                        cur_colors[v] = c
                        improved = True
                        break
                if improved:
                    break  # Break vertex loop, restart color loop
                # Try Kempe chains for each lower color
                for c in range(target_color):
                    if c in neighbor_colors:
                        continue
                    # Check if v is connected to any vertex of color c via a Kempe chain (c, target_color)
                    # We'll do BFS/DFS on the subgraph of colors c and target_color
                    visited = set()
                    stack = [v]
                    visited.add(v)
                    found_c = False
                    while stack:
                        node = stack.pop()
                        if cur_colors[node] == c:
                            found_c = True
                            break
                        for u in neighbors[node]:
                            if u not in visited and cur_colors[u] in (c, target_color):
                                visited.add(u)
                                stack.append(u)
                    if not found_c:
                        # Swap colors c and target_color in the component containing v
                        for node in visited:
                            if cur_colors[node] == c:
                                cur_colors[node] = target_color
                            elif cur_colors[node] == target_color:
                                cur_colors[node] = c
                        improved = True
                        break
                if improved:
                    break
            if improved:
                break
        if improved:
            colors = cur_colors
            # Recompute k
            k = max(colors) + 1 if n > 0 else 0
        else:
            break
    return colors, k

def reduce_color_count(n, neighbors, colors, k):
    if k <= 1:
        return colors, False
    # Try to eliminate the highest color class (k-1)
    target_color = k - 1
    vertices = [v for v in range(n) if colors[v] == target_color]
    if not vertices:
        # Already eliminated
        new_k = max(colors) + 1 if n > 0 else 0
        return colors, new_k < k
    # Try to recolor each vertex in this class to a lower color
    # We'll attempt to reassign each vertex one by one, using Kempe chains if needed
    # Make a copy to avoid side effects during attempts
    cur_colors = colors[:]
    success = False
    for v in vertices:
        # Try direct reassignment to any color < target_color
        neighbor_colors = {cur_colors[u] for u in neighbors[v] if cur_colors[u] != -1}
        for c in range(target_color):
            if c not in neighbor_colors:
                cur_colors[v] = c
                success = True
                break
        if success:
            break
        # Try Kempe chains for each lower color
        for c in range(target_color):
            if c in neighbor_colors:
                continue
            # Check if v is connected to any vertex of color c via Kempe chain (c, target_color)
            visited = set()
            stack = [v]
            visited.add(v)
            found_c = False
            while stack:
                node = stack.pop()
                if cur_colors[node] == c:
                    found_c = True
                    break
                for u in neighbors[node]:
                    if u not in visited and cur_colors[u] in (c, target_color):
                        visited.add(u)
                        stack.append(u)
            if not found_c:
                # Swap colors c and target_color in the component containing v
                for node in visited:
                    if cur_colors[node] == c:
                        cur_colors[node] = target_color
                    elif cur_colors[node] == target_color:
                        cur_colors[node] = c
                success = True
                break
        if success:
            break
    if success:
        # Recompute the color count
        new_k = max(cur_colors) + 1 if n > 0 else 0
        if new_k < k:
            return cur_colors, True
    return colors, False

import math
