def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix: square and binary (0/1)
    is_matrix = (len(adj[0]) == n) and all(
        isinstance(x, int) and x in (0, 1) for row in adj for x in row
    )

    # Build adjacency list
    if is_matrix:
        neighbors = [
            [v for v in range(n) if adj[u][v] == 1] for u in range(n)
        ]
    else:
        neighbors = [list(lst) for lst in adj]

    # Precompute degree
    degree = [len(neighbors[u]) for u in range(n)]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = [False] * n
            for v in neighbors[u]:
                if color[v] != -1:
                    used[color[v]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[u] = c
        return color

    # DSATUR heuristic
    def dsatur():
        color = [-1] * n
        saturated = [set() for _ in range(n)]
        uncolored = set(range(n))

        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            best = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = len(saturated[v])
                deg = sum(1 for u in neighbors[v] if u in uncolored)
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (
                    sat == best_sat and deg == best_deg and v > best
                ):
                    best = v
                    best_sat = sat
                    best_deg = deg
            v = best
            # Assign smallest available color
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    saturated[u].add(c)
        return color

    # RLF heuristic
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S = {v}
            # U: vertices not adjacent to S (eligible), W: vertices adjacent to S (ineligible)
            U = {u for u in uncolored if u != v and all(u not in neighbors[w] for w in S)}
            W = {u for u in uncolored if u != v and any(u in neighbors[w] for w in S)}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_score = -1
                best_degU = n + 1
                for u in U:
                    score = sum(1 for w in neighbors[u] if w in W)
                    degU = sum(1 for w in neighbors[u] if w in U)
                    if score > best_score or (score == best_score and degU < best_degU) or (
                        score == best_score and degU == best_degU and u < best_u
                    ):
                        best_u = u
                        best_score = score
                        best_degU = degU
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Welsh-Powell (largest first)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: degree[x], reverse=True)
        return greedy_color(order)

    # Smallest-last ordering (degeneracy ordering)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        order = []
        deg = degree[:]
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            remaining.remove(v)
            order.append(v)
            # Decrease degree of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    old_deg = deg[u]
                    deg[u] -= 1
                    if old_deg <= max_deg:
                        buckets[old_deg].remove(u)
                    if deg[u] <= max_deg:
                        buckets[deg[u]].append(u)
                    if deg[u] < ptr:
                        ptr = deg[u]
        # Color in reverse order
        return greedy_color(order[::-1])

    # Kempe chain color reduction
    def kempe_reduce(color_in):
        color = color_in[:]
        k = max(color) + 1 if n > 0 else 0
        improved = True
        while improved and k > 1:
            improved = False
            # Try to eliminate color k-1
            target_color = k - 1
            vertices = [v for v in range(n) if color[v] == target_color]
            if not vertices:
                k -= 1
                improved = True
                continue
            # Try to recolor each vertex in target_color
            for v in vertices:
                # Try direct move to a lower color
                neighbor_colors = {color[u] for u in neighbors[v]}
                for c in range(target_color):
                    if c not in neighbor_colors:
                        color[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chains
                for c in range(target_color):
                    if c in neighbor_colors:
                        continue
                    # Find Kempe chain of (target_color, c) containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if color[node] == target_color or color[node] == c:
                            component.add(node)
                            for w in neighbors[node]:
                                if w not in visited and (color[w] == target_color or color[w] == c):
                                    stack.append(w)
                    # Check if any neighbor of v in component has color c -> swapping would cause conflict
                    conflict = False
                    for node in component:
                        for w in neighbors[node]:
                            if w not in component and color[w] == c:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # Swap colors in component
                        for node in component:
                            if color[node] == target_color:
                                color[node] = c
                            elif color[node] == c:
                                color[node] = target_color
                        improved = True
                        break
                if improved:
                    break
            if not improved:
                break
            # Recompute k
            k = max(color) + 1
        return color

    # Run all heuristics and keep the best (fewest colors)
    best_color = None
    best_k = float('inf')

    for heuristic in [dsatur, rlf, welsh_powell, smallest_last]:
        try:
            col = heuristic()
            k = max(col) + 1 if n > 0 else 0
            if k < best_k or (k == best_k and best_color is None):
                best_k = k
                best_color = col
        except Exception:
            continue

    # Apply Kempe reduction to further improve
    if best_color is not None:
        best_color = kempe_reduce(best_color)
        best_k = max(best_color) + 1 if n > 0 else 0

    # Fallback: greedy by original order if nothing worked
    if best_color is None:
        best_color = greedy_color(list(range(n)))

    return best_color

