def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect if adjacency matrix
    is_matrix = False
    if len(adj[0]) == n:
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor sets
    if is_matrix:
        neighbors = [set(j for j in range(n) if adj[i][j] == 1) for i in range(n)]
    else:
        neighbors = [set(adj[i]) for i in range(n)]

    # Exact coloring for small n
    if n <= 20:
        return exact_coloring(neighbors, n)

    # Try DSATUR for upper bound
    dsatur_colors = dsatur_coloring(neighbors, n)
    ub = max(dsatur_colors) + 1

    # Try to improve with Kempe chains
    improved_colors = kempe_improve(dsatur_colors[:], neighbors, n)
    if max(improved_colors) + 1 < ub:
        ub = max(improved_colors) + 1
        dsatur_colors = improved_colors

    # Try RLF for upper bound
    rlf_colors = rlf_coloring(neighbors, n)
    rlf_ub = max(rlf_colors) + 1
    if rlf_ub < ub:
        ub = rlf_ub
        dsatur_colors = rlf_colors[:]
        improved_colors = kempe_improve(dsatur_colors[:], neighbors, n)
        if max(improved_colors) + 1 < ub:
            ub = max(improved_colors) + 1
            dsatur_colors = improved_colors

    # Binary search for minimal k
    lb = max_clique_lower_bound(neighbors, n)
    if lb < 1:
        lb = 1
    if ub < lb:
        ub = lb

    best_colors = dsatur_colors[:]
    best_k = ub

    while lb <= ub:
        mid = (lb + ub) // 2
        colors = backtrack_with_dsatur(neighbors, n, mid)
        if colors is not None:
            best_k = mid
            best_colors = colors[:]
            ub = mid - 1
        else:
            lb = mid + 1

    return best_colors

def exact_coloring(neighbors, n):
    best_coloring = None
    best_k = n

    def backtrack(idx, colors, used_k):
        nonlocal best_coloring, best_k
        if used_k >= best_k:
            return
        if idx == n:
            best_coloring = colors[:]
            best_k = used_k
            return
        # Try existing colors
        for c in range(used_k):
            conflict = False
            for nb in neighbors[idx]:
                if colors[nb] == c:
                    conflict = True
                    break
            if not conflict:
                colors[idx] = c
                backtrack(idx + 1, colors, used_k)
                colors[idx] = -1
        # Try new color
        colors[idx] = used_k
        backtrack(idx + 1, colors, used_k + 1)
        colors[idx] = -1

    colors = [-1] * n
    backtrack(0, colors, 0)
    return best_coloring if best_coloring is not None else [0] * n

def dsatur_coloring(neighbors, n):
    colors = [-1] * n
    saturated = [set() for _ in range(n)]
    uncolored = set(range(n))

    while uncolored:
        # Select vertex with max saturation degree
        max_sat = -1
        candidates = []
        for v in uncolored:
            sat = len(saturated[v])
            if sat > max_sat:
                max_sat = sat
                candidates = [v]
            elif sat == max_sat:
                candidates.append(v)
        # Tie-break by degree in uncolored subgraph
        if len(candidates) > 1:
            max_deg = -1
            selected = candidates[0]
            for v in candidates:
                deg = sum(1 for nb in neighbors[v] if nb in uncolored)
                if deg > max_deg:
                    max_deg = deg
                    selected = v
                elif deg == max_deg and v < selected:
                    selected = v
            v = selected
        else:
            v = candidates[0]
        # Assign smallest available color
        used = saturated[v]
        c = 0
        while c in used:
            c += 1
        colors[v] = c
        uncolored.remove(v)
        # Update saturation of neighbors
        for nb in neighbors[v]:
            if nb in uncolored:
                saturated[nb].add(c)
    return colors

def rlf_coloring(neighbors, n):
    colors = [-1] * n
    color = 0
    uncolored = set(range(n))

    while uncolored:
        # Find vertex with max degree in uncolored subgraph
        max_deg = -1
        v0 = None
        for v in uncolored:
            deg = sum(1 for nb in neighbors[v] if nb in uncolored)
            if deg > max_deg:
                max_deg = deg
                v0 = v
            elif deg == max_deg and v < v0:
                v0 = v
        # Build independent set for this color
        independent_set = {v0}
        uncolored.remove(v0)
        # U: vertices not adjacent to any in independent_set
        # W: vertices adjacent to at least one in independent_set
        U = set()
        W = set()
        for v in uncolored:
            if any(nb in independent_set for nb in neighbors[v]):
                W.add(v)
            else:
                U.add(v)
        # Greedily add to independent set
        while U:
            # Select u in U with max neighbors in W
            best_u = None
            best_score = -1
            for u in U:
                score = sum(1 for nb in neighbors[u] if nb in W)
                if score > best_score:
                    best_score = score
                    best_u = u
                elif score == best_score:
                    # Tie-break by min degree in U
                    deg_u = sum(1 for nb in neighbors[u] if nb in U)
                    deg_best = sum(1 for nb in neighbors[best_u] if nb in U) if best_u is not None else float('inf')
                    if deg_u < deg_best or (deg_u == deg_best and u < best_u):
                        best_u = u
            if best_u is None:
                break
            independent_set.add(best_u)
            U.remove(best_u)
            # Move neighbors of best_u from U to W
            for nb in neighbors[best_u]:
                if nb in U:
                    U.remove(nb)
                    W.add(nb)
        # Assign color to independent set
        for v in independent_set:
            colors[v] = color
        color += 1
    return colors

def kempe_improve(colors, neighbors, n):
    # Try to eliminate the last color class
    max_color = max(colors) if n > 0 else -1
    if max_color < 0:
        return colors
    # Try multiple iterations
    for _ in range(10):  # Limit iterations for time
        color_classes = [[] for _ in range(max_color + 1)]
        for v in range(n):
            color_classes[colors[v]].append(v)
        # Find smallest non-empty color class (starting from highest color)
        target_color = -1
        min_size = float('inf')
        for c in range(max_color, -1, -1):
            if color_classes[c] and len(color_classes[c]) < min_size:
                min_size = len(color_classes[c])
                target_color = c
        if target_color == -1 or min_size == 0:
            break
        # Try to recolor each vertex in target_color
        made_change = False
        for v in color_classes[target_color][:]:  # Copy list as we may modify
            # Try to move to a lower color directly
            for c in range(target_color):
                conflict = False
                for nb in neighbors[v]:
                    if colors[nb] == c:
                        conflict = True
                        break
                if not conflict:
                    colors[v] = c
                    made_change = True
                    break
            if made_change:
                break
            # Try Kempe chains with each lower color
            for c in range(target_color):
                # Find Kempe chain component of v in colors {c, target_color}
                if colors[v] != target_color:
                    continue
                visited = set()
                stack = [v]
                visited.add(v)
                component = set()
                while stack:
                    node = stack.pop()
                    component.add(node)
                    for nb in neighbors[node]:
                        if nb not in visited and (colors[nb] == c or colors[nb] == target_color):
                            visited.add(nb)
                            stack.append(nb)
                # Check if swapping would cause conflict
                swap_ok = True
                for node in component:
                    for nb in neighbors[node]:
                        if nb not in component and colors[nb] == (c if colors[node] == target_color else target_color):
                            swap_ok = False
                            break
                    if not swap_ok:
                        break
                if swap_ok:
                    # Perform swap
                    for node in component:
                        colors[node] = c if colors[node] == target_color else target_color
                    made_change = True
                    break
            if made_change:
                break
        if not made_change:
            break
        # Update max_color
        max_color = max(colors)
    return colors

def max_clique_lower_bound(neighbors, n):
    # Simple greedy clique finding for lower bound
    max_clique = 0
    # Try multiple random orderings
    for _ in range(10):
        order = list(range(n))
        random.shuffle(order)
        clique = []
        for v in order:
            if all(v in neighbors[u] for u in clique):
                clique.append(v)
        if len(clique) > max_clique:
            max_clique = len(clique)
    # Also try degree ordering
    order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    clique = []
    for v in order:
        if all(v in neighbors[u] for u in clique):
            clique.append(v)
    if len(clique) > max_clique:
        max_clique = len(clique)
    return max_clique

def backtrack_with_dsatur(neighbors, n, k_limit):
    colors = [-1] * n
    saturated = [set() for _ in range(n)]
    uncolored = set(range(n))

    def backtrack():
        if not uncolored:
            return True
        # Select vertex with max saturation degree
        max_sat = -1
        candidates = []
        for v in uncolored:
            sat = len(saturated[v])
            if sat > max_sat:
                max_sat = sat
                candidates = [v]
            elif sat == max_sat:
                candidates.append(v)
        # Tie-break by degree in uncolored subgraph
        if len(candidates) > 1:
            max_deg = -1
            selected = candidates[0]
            for v in candidates:
                deg = sum(1 for nb in neighbors[v] if nb in uncolored)
                if deg > max_deg:
                    max_deg = deg
                    selected = v
                elif deg == max_deg and v < selected:
                    selected = v
            v = selected
        else:
            v = candidates[0]
        # Try colors in order
        for c in range(k_limit):
            if c in saturated[v]:
                continue
            # Check if color c is valid (should be implied by saturated, but double-check)
            conflict = False
            for nb in neighbors[v]:
                if colors[nb] == c:
                    conflict = True
                    break
            if conflict:
                continue
            # Assign color c
            colors[v] = c
            uncolored.remove(v)
            # Update saturated sets
            updated = []
            for nb in neighbors[v]:
                if nb in uncolored and c not in saturated[nb]:
                    saturated[nb].add(c)
                    updated.append(nb)
            # Recurse
            if backtrack():
                return True
            # Backtrack
            for nb in updated:
                saturated[nb].discard(c)
            uncolored.add(v)
            colors[v] = -1
        return False

    if backtrack():
        return colors
    return None

