    # Detect input type: adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if it's a binary matrix (0/1)
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and degree array
    if is_matrix:
        neighbors = []
        for i in range(n):
            row = []
            for j in range(n):
                if adj[i][j] == 1:
                    row.append(j)
            neighbors.append(row)
    else:
        neighbors = adj  # already adjacency list

    deg = [len(neighbors[i]) for i in range(n)]

    # Trivial cases
    if all(d == 0 for d in deg):
        return [0] * n
    if all(d == n - 1 for d in deg):
        return list(range(n))

    # DSATUR algorithm
    color = [-1] * n
    # saturation: list of sets, each set contains colors used by colored neighbors
    saturation = [set() for _ in range(n)]
    # number of colored neighbors (for tie-breaking)
    colored_neighbor_count = [0] * n

    # Helper: get uncolored neighbors count for tie-breaking
    def get_uncolored_degree(v):
        count = 0
        for u in neighbors[v]:
            if color[u] == -1:
                count += 1
        return count

    # Main loop: color all vertices
    for _ in range(n):
        # Select vertex: max saturation degree, then max uncolored degree, then random
        v = -1
        max_sat = -1
        max_uncolored_deg = -1
        for i in range(n):
            if color[i] != -1:
                continue
            sat_i = len(saturation[i])
            if sat_i > max_sat:
                max_sat = sat_i
                max_uncolored_deg = get_uncolored_degree(i)
                v = i
            elif sat_i == max_sat:
                uncolored_deg_i = get_uncolored_degree(i)
                if uncolored_deg_i > max_uncolored_deg:
                    max_uncolored_deg = uncolored_deg_i
                    v = i
                elif uncolored_deg_i == max_uncolored_deg:
                    # Break tie randomly
                    if random.random() < 0.5:
                        v = i
        # If no vertex found (should not happen), pick first uncolored
        if v == -1:
            for i in range(n):
                if color[i] == -1:
                    v = i
                    break

        # Find smallest available color (mex)
        used = saturation[v]
        c = 0
        while c in used:
            c += 1
        color[v] = c

        # Update saturation and colored neighbor count for all uncolored neighbors
        for u in neighbors[v]:
            if color[u] == -1:
                saturation[u].add(c)
                colored_neighbor_count[u] += 1

    # Local search: Kempe chain refinement to reduce color count
    max_color = max(color) if n > 0 else -1
    if max_color < 0:
        return color

    # Try to reduce colors from max_color down to 0
    for target_color in range(max_color, 0, -1):
        # Collect vertices with color = target_color
        class_vertices = [i for i in range(n) if color[i] == target_color]
        if not class_vertices:
            continue  # This color class is already empty

        # Try to recolor each vertex in this class to a lower color
        made_progress = False
        for v in class_vertices:
            # Try direct reassignment to a lower color
            neighbor_colors = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    neighbor_colors.add(color[u])
            for c in range(target_color):
                if c not in neighbor_colors:
                    # Direct move possible
                    color[v] = c
                    made_progress = True
                    break
            if made_progress:
                break  # Re-start the scan for this target_color after a change

            # Try Kempe chains for each lower color
            for c in range(target_color):
                # We'll attempt to swap colors c and target_color in the component containing v
                # Only if v is not adjacent to any vertex of color c (otherwise swap would conflict immediately)
                if any(color[u] == c for u in neighbors[v]):
                    continue  # Adjacent to color c, swap would cause conflict

                # Build the Kempe chain: connected component of v in the subgraph of colors {c, target_color}
                stack = [v]
                visited = set([v])
                # We'll also track if we encounter any vertex that, when swapped, would pull a vertex of color c into the class
                # Actually, we want to know if the component contains any vertex of color c that is adjacent to a vertex of color target_color (outside the component?) 
