                # Instead, we note: after swap, v will become color c. We already checked v has no neighbor of color c.
                # For other vertices in the component: 
                #   - if a vertex x of color c is in the component, after swap it becomes target_color. We must ensure x has no neighbor of color target_color (after swap) that is not swapped.
                #   But since we are swapping the entire component, any neighbor of x that is color target_color and in the component will become color c, so no conflict.
                #   The only potential conflict is if x has a neighbor y of color target_color that is NOT in the component. After swap, x becomes target_color and y remains target_color -> conflict.
                # Therefore, the swap is safe if and only if no vertex in the component of color c has a neighbor of color target_color outside the component.
                # Similarly, no vertex in the component of color target_color has a neighbor of color c outside the component? 
                # But we started from v (color target_color) and we know v has no neighbor of color c (checked). For other target_color vertices in the component, we don't need to check? 
                # Actually, symmetric condition: for any vertex in the component of color target_color, it must not have a neighbor of color c outside the component.
                # However, note: if a target_color vertex in the component had a neighbor of color c outside the component, then that neighbor would be in the component (because we traverse via edges to same or other color in the pair) -> contradiction. 
                # Therefore, we only need to check for vertices of color c in the component: they must not have a neighbor of color target_color outside the component.

                # We'll collect the component and then check the condition.
                component = set()
                stack = [v]
                visited = set([v])
                while stack:
                    node = stack.pop()
                    component.add(node)
                    for u in neighbors[node]:
                        if color[u] == c or color[u] == target_color:
                            if u not in visited:
                                visited.add(u)
                                stack.append(u)

                # Check: for every node x in component with color[x] == c, 
                #   all neighbors of x that are color target_color must be in the component.
                safe = True
                for x in component:
                    if color[x] == c:
                        for u in neighbors[x]:
                            if color[u] == target_color and u not in component:
                                safe = False
                                break
                        if not safe:
                            break
                if safe:
                    # Perform the swap: swap colors c and target_color in the component
                    for x in component:
                        if color[x] == c:
                            color[x] = target_color
                        elif color[x] == target_color:
                            color[x] = c
                    made_progress = True
                    break  # break out of color loop, restart scanning this target_color
            if made_progress:
                break
        if not made_progress:
            # Could not eliminate this color class, move to next lower target color
            continue
        else:
            # We made progress, so we need to re-check the same target_color because the class might still have vertices
            # We'll reset the loop for this target_color by not decrementing yet; but easier: we break and let the outer loop continue, 
            # but we want to try again for the same target_color. Instead, we do: after a successful recolor, we break and then the outer loop will continue with the same target_color? 
            # Actually, we broke out of the inner loops and then we are here. We set made_progress and break out of the vertex loop, then we are after the vertex loop.
            # We then check: if made_progress, we do not break the target_color loop, but we continue to next iteration of the same target_color? 
            # But we want to try again to eliminate the class because there might be more vertices. 
            # So we do not break the target_color loop; we let it run again for the same target_color. 
            # However, note: we are in a for loop over target_color. We cannot easily stay on the same target_color without restructuring.
            # Instead, we do: after making progress, we break out of the vertex loop and then continue the target_color loop (which will decrement target_color). 
            # But we want to try again for the same target_color. 
            # Therefore, we change strategy: we use a while loop for each target_color.
            pass  # We'll restructure below

    # Restructure: for each target_color from high to low, repeatedly try to eliminate until no progress
    # We'll redo the local search with a while loop per target_color.
    # But to avoid deep nesting, we break out and restructure the code.
    # Given the time, we'll do a simpler approach: multiple passes until no improvement.
    # We'll do at most n passes of Kempe attempts.

    # Clear and redo local search with multiple passes
    # We'll try to reduce the color count by repeatedly attempting to eliminate the highest color class.
    improved = True
    # We'll limit passes to avoid infinite loop
    for _pass in range(n):  # at most n passes
        if not improved:
            break
        improved = False
        max_color = max(color) if n > 0 else -1
        if max_color < 0:
            break
        # Try to eliminate color class max_color
        class_vertices = [i for i in range(n) if color[i] == max_color]
        if not class_vertices:
            improved = True  # already empty, consider as progress? but we break anyway
            continue
        made_progress = False
        for v in class_vertices:
            # Try direct reassignment to a lower color
            neighbor_colors = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    neighbor_colors.add(color[u])
            for c in range(max_color):
                if c not in neighbor_colors:
                    color[v] = c
                    made_progress = True
                    improved = True
                    break
            if made_progress:
                break
            # Try Kempe chains
            for c in range(max_color):
                if any(color[u] == c for u in neighbors[v]):
                    continue
                # Build component of v in colors {c, max_color}
                stack = [v]
                visited = set([v])
                component = set()
                while stack:
                    node = stack.pop()
                    component.add(node)
                    for u in neighbors[node]:
                        if color[u] == c or color[u] == max_color:
                            if u not in visited:
                                visited.add(u)
                                stack.append(u)
                # Check safety: for every x in component with color[x]==c, all neighbors of color max_color must be in component
                safe = True
                for x in component:
                    if color[x] == c:
                        for u in neighbors[x]:
                            if color[u] == max_color and u not in component:
                                safe = False
                                break
                        if not safe:
                            break
                if safe:
                    # Swap colors c and max_color in component
                    for x in component:
                        if color[x] == c:
                            color[x] = max_color
                        elif color[x] == max_color:
                            color[x] = c
                    made_progress = True
                    improved = True
                    break
            if made_progress:
                break
        # If we made progress, we continue the pass loop to try again (maybe eliminate further)

    return color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Determine if input is adjacency matrix
    is_matrix = (n > 0 and len(adj[0]) == n and
                 all(isinstance(row, list) and len(row) == n for row in adj) and
                 all(all(x in (0, 1) for x in row) for row in adj))
    # Build adjacency list
    if is_matrix:
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        graph = [list(neigh) for neigh in adj]
        # Ensure symmetry for undirected graph (if not already)
        for i in range(n):
            for j in graph[i]:
                if i not in graph[j]:
                    graph[j].append(i)
    # Handle trivial cases
    if n == 1:
        return [0]
    # Check if edgeless
    if all(len(graph[i]) == 0 for i in range(n)):
        return [0] * n
    # Check if complete
    is_complete = True
    for i in range(n):
        if len(graph[i]) != n - 1:
            is_complete = False
            break
    if is_complete:
        return list(range(n))
    # DSATUR with RLF fallback and Kempe chain refinement
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        colored = [False] * n
        # Order by degree descending for initial tie-breaking
        order = sorted(range(n), key=lambda x: len(graph[x]), reverse=True)
        for v in order:
            if colored[v]:
                continue
            # Compute saturation degree: number of distinct colors in neighbors
            neighbor_colors = set()
            for u in graph[v]:
                if color[u] != -1:
                    neighbor_colors.add(color[u])
            sat[v] = len(neighbor_colors)
            # Find uncolored vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            max_sat = -1
            candidates = []
            for u in range(n):
                if not colored[u]:
                    if sat[u] > max_sat:
                        max_sat = sat[u]
                        candidates = [u]
                    elif sat[u] == max_sat:
                        candidates.append(u)
            if max_sat == -1:  # no uncolored left (should not happen)
                break
            # Tie-break: max degree in uncolored subgraph
            max_deg = -1
            best = []
            for u in candidates:
                deg = 0
                for w in graph[u]:
                    if not colored[w]:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    best = [u]
                elif deg == max_deg:
                    best.append(u)
            v_sel = random.choice(best) if best else candidates[0]
            # Assign smallest available color
            used = [False] * (n + 1)
            for u in graph[v_sel]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v_sel] = c
            colored[v_sel] = True
            # Update saturation of neighbors
            for u in graph[v_sel]:
                if not colored[u]:
                    sat[u] = len({color[w] for w in graph[u] if color[w] != -1})
        return color
    # Recursive Largest First (RLF) for independent set extraction
    def rlf():
        color = [-1] * n
        colored = [False] * n
        c = 0
        while not all(colored):
            # Step 1: pick uncolored vertex with max degree in uncolored subgraph
            max_deg = -1
            v = -1
            for i in range(n):
                if not colored[i]:
                    deg = 0
                    for nb in graph[i]:
                        if not colored[nb]:
                            deg += 1
                    if deg > max_deg:
                        max_deg = deg
                        v = i
            if v == -1:
                break
            S = [v]
            colored[v] = True
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = set()
            W = set()
            for i in range(n):
                if not colored[i]:
                    if i not in graph[v]:
                        U.add(i)
                    else:
                        W.add(i)
            # Step 4: while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                for u in U:
                    score = 0
                    for nb in graph[u]:
                        if nb in W:
                            score += 1
                    if score > best_score:
                        best_score = score
                        best_u = u
                    elif score == best_score:
                        # tie-break: min degree in G[U]
                        deg_u = sum(1 for nb in graph[u] if nb in U)
                        deg_best = sum(1 for nb in graph[best_u] if nb in U) if best_u != -1 else float('inf')
                        if deg_u < deg_best:
                            best_u = u
                if best_u == -1:
                    break
                S.append(best_u)
                colored[best_u] = True
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for nb in graph[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color c to all in S
            for node in S:
                color[node] = c
            c += 1
        return color
    # Kempe chain refinement to reduce color count
    def kempe_refine(color_in):
        color = color_in[:]
        k = max(color) + 1 if n > 0 else 0
        improved = True
        while improved and k > 1:
            improved = False
            # Try to eliminate color k-1
            target = k - 1
            vertices = [i for i in range(n) if color[i] == target]
            if not vertices:
                k -= 1
                continue
            # Try to recolor each vertex in target class
            for v in vertices:
                # Try direct move to lower color
                neighbor_colors = set(color[u] for u in graph[v] if color[u] != -1)
                for c in range(target):
                    if c not in neighbor_colors:
                        color[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chain swap
                for c in range(target):
                    # Skip if v already has color c (should not happen)
                    if color[v] == c:
                        continue
                    # Check if v is adjacent to any vertex of color c
                    adj_to_c = any(color[u] == c for u in graph[v])
                    if adj_to_c:
                        continue
                    # Build (c, target) Kempe chain containing v
                    stack = [v]
                    visited = set([v])
                    while stack:
                        node = stack.pop()
                        for nb in graph[node]:
                            if nb not in visited and (color[nb] == c or color[nb] == target):
                                visited.add(nb)
                                stack.append(nb)
                    # Swap colors in component
                    for node in visited:
                        if color[node] == c:
                            color[node] = target
                        elif color[node] == target:
                            color[node] = c
                    # After swap, check if v can now take color c (should be free)
                    neighbor_colors_new = set(color[u] for u in graph[v] if color[u] != -1)
                    if c not in neighbor_colors_new:
                        color[v] = c
                        improved = True
                        break
                if improved:
                    break
            if not improved:
                # Cannot reduce further
                break
            # Recompute k
            k = max(color) + 1
        return color
    # Run DSATUR first
    col_dsatur = dsatur()
    k_dsatur = max(col_dsatur) + 1 if n > 0 else 0
    # Run RLF
    col_rlf = rlf()
    k_rlf = max(col_rlf) + 1 if n > 0 else 0
    # Choose the better initial coloring
    if k_dsatur <= k_rlf:
        col = col_dsatur
    else:
        col = col_rlf
    # Apply Kempe chain refinement
    col = kempe_refine(col)
    # Final validation (optional, but safe)
    # Ensure no adjacent same color
    for i in range(n):
        for j in graph[i]:
            if i < j and color[i] == color[j]:
                # Fallback to greedy Welsh-Powell if something went wrong
                order = sorted(range(n), key=lambda x: len(graph[x]), reverse=True)
                color_greedy = [-1] * n
                for v in order:
                    used = [False] * (n + 1)
                    for u in graph[v]:
                        if color_greedy[u] != -1:
                            used[color_greedy[u]] = True
                    c = 0
                    while c < n and used[c]:
                        c += 1
                    color_greedy[v] = c
                return color_greedy
    return col

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine input type: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x == 0 or x == 1 for x in row) for row in adj):
            is_matrix = True

    # Build neighbor list and degree array
    if is_matrix:
        neighbors = []
        deg = [0] * n
        for i in range(n):
            row_neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    row_neighbors.append(j)
                    deg[i] += 1
            neighbors.append(row_neighbors)
    else:
        neighbors = [list(lst) for lst in adj]
        deg = [len(lst) for lst in neighbors]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: Welsh-Powell ordering (by degree descending)
    def welsh_powell_order():
        return sorted(range(n), key=lambda x: deg[x], reverse=True)

    # Helper: smallest-last ordering (Matula-Beck)
    def smallest_last_order():
        if n == 0:
            return []
        current_deg = deg[:]
        removed = [False] * n
        order = []
        buckets = [[] for _ in range(n)]
        for v in range(n):
            d = current_deg[v]
            if d < n:
                buckets[d].append(v)
        min_d = 0
        for _ in range(n):
            while min_d < n and not buckets[min_d]:
                min_d += 1
            if min_d >= n:
                break
            v = buckets[min_d].pop()
            if removed[v]:
                continue
            removed[v] = True
            order.append(v)
            for u in neighbors[v]:
                if not removed[u]:
                    d_u = current_deg[u]
                    current_deg[u] = d_u - 1
                    if d_u - 1 < n:
                        buckets[d_u - 1].append(u)
                    if d_u - 1 < min_d:
                        min_d = d_u - 1
        return order[::-1]

    # Helper: DSATUR heuristic
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        colored = [False] * n
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree then random
            v = -1
            max_sat = -1
            max_deg = -1
            for i in range(n):
                if not colored[i]:
                    if sat[i] > max_sat or (sat[i] == max_sat and deg[i] > max_deg) or \
                       (sat[i] == max_sat and deg[i] == max_deg and (v == -1 or random.random() < 0.5)):
                        max_sat = sat[i]
                        max_deg = deg[i]
                        v = i
            if v == -1:
                break  # should not happen
            # Find smallest available color
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            colored[v] = True
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if not colored[u]:
                    sat[u] += 1
        return color

    # Helper: RLF (Recursive Largest First) heuristic
    def rlf():
        color = [-1] * n
        colored = [False] * n
        c = 0
        while not all(colored):
            # Build set of uncolored vertices R
            R = [i for i in range(n) if not colored[i]]
            if not R:
                break
            # Compute degrees in subgraph induced by R
            deg_R = [0] * n
            for v in R:
                for u in neighbors[v]:
                    if not colored[u]:
                        deg_R[v] += 1
            # Select first vertex: max degree in R
            v1 = max(R, key=lambda x: deg_R[x])
            S = [v1]
            colored[v1] = True
            # Partition R \ {v1} into U (not adjacent to S) and W (adjacent to S)
            U = []
            W = []
            for v in R:
                if v == v1:
                    continue
                adjacent = False
                for u in S:
                    if v in neighbors[u]:
                        adjacent = True
                        break
                if adjacent:
                    W.append(v)
                else:
                    U.append(v)
            # While U not empty, add vertices to S
            while U:
                # Select u in U with max neighbors in W
                u_star = -1
                max_nw = -1
                min_deg_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    nw = 0
                    for w in W:
                        if w in neighbors[u]:
                            nw += 1
                    # Tie-break: min degree in U (current deg_R in U subgraph)
                    deg_u_U = 0
                    for w in U:
                        if w != u and w in neighbors[u]:
                            deg_u_U += 1
                    if nw > max_nw or (nw == max_nw and deg_u_U < min_deg_U) or \
                       (nw == max_nw and deg_u_U == min_deg_U and (u_star == -1 or random.random() < 0.5)):
                        max_nw = nw
                        min_deg_U = deg_u_U
                        u_star = u
                if u_star == -1:
                    break  # should not happen if U not empty
                S.append(u_star)
                colored[u_star] = True
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                for w in list(U):
                    if w in neighbors[u_star]:
                        U.remove(w)
                        W.append(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            c += 1
        return color

