                        min_u_deg_in_U = u_deg_in_U
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        if u_deg_in_U < min_u_deg_in_U:
                            min_u_deg_in_U = u_deg_in_U
                            best_u = u

                if best_u == -1:
                    break  # No valid vertex, should not happen

                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                to_move = set()
                for u in U:
                    if best_u in neighbor_sets[u]:
                        to_move.add(u)
                U -= to_move
                W |= to_move

            # Assign color to all in S
            for v in S:
                colors[v] = color
                uncolored.remove(v)

            color += 1

        return colors

    # Welsh-Powell implementation
    def welsh_powell():
        # Order by degree descending
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        colors = [-1] * n

        for v in order:
            used = set()
            for u in neighbors[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c

        return colors

    # Smallest-Last ordering implementation
    def smallest_last():
        # Compute core numbers and removal order
        degree = [len(neighbors[i]) for i in range(n)]
        # Buckets for degrees
        max_deg = max(degree) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            if d <= max_deg:
                bins[d].append(v)

        # Pointer to current non-empty bin
        pos = 0
        order = []
        # Copy of degree for modification
        curr_degree = degree[:]
        # Set of removed vertices
        removed = [False] * n

        for _ in range(n):
            # Find non-empty bin
            while pos <= max_deg and not bins[pos]:
                pos += 1
            if pos > max_deg:
                break  # Should not happen

            v = bins[pos].pop()
            if removed[v]:
                # Find another in this bin
                while bins[pos] and removed[bins[pos][-1]]:
                    bins[pos].pop()
                if not bins[pos]:
                    pos += 1
                    while pos <= max_deg and not bins[pos]:
                        pos += 1
                    if pos > max_deg:
                        break
                    v = bins[pos].pop()
                else:
                    v = bins[pos].pop()

            order.append(v)
            removed[v] = True
            # Update neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    d = curr_degree[u]
                    # Remove u from its current bin
                    if d <= max_deg and u in bins[d]:
                        bins[d].remove(u)
                    curr_degree[u] -= 1
                    d_new = curr_degree[u]
                    if d_new <= max_deg:
                        bins[d_new].append(u)

        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = set()
            for u in neighbors[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c

        return colors

    # Kempe chain refinement to reduce colors
    def kempe_refine(colors):
        # Determine current number of colors
        max_color = max(colors) if n > 0 else -1
        if max_color < 0:
            return colors

        # Build color classes
        color_classes = [[] for _ in range(max_color + 1)]
        for v in range(n):
            c = colors[v]
            if c != -1:
                color_classes[c].append(v)

        # Try to eliminate color classes from highest down
        changed = True
        while changed and max_color >= 0:
            changed = False
            # Find smallest non-empty color class (by index, but we try high colors first for reduction)
            # We try to reduce the highest color first
            for c in range(max_color, -1, -1):
                if not color_classes[c]:
                    continue
                # Try to recolor each vertex in class c to a lower color
                for v in color_classes[c][:]:  # iterate over copy
                    # Try direct reassignment to lower colors
                    neighbor_colors = set()
                    for u in neighbors[v]:
                        if colors[u] != -1:
                            neighbor_colors.add(colors[u])

                    for c_low in range(c):
                        if c_low not in neighbor_colors:
                            # Direct move possible
                            colors[v] = c_low
                            color_classes[c].remove(v)
                            color_classes[c_low].append(v)
                            changed = True
                            break
                    if changed:
                        break

                    # Try Kempe chains
                    for c_low in range(c):
                        # Check if v can be swapped via Kempe chain (c, c_low)
                        # Only consider if c_low is not in neighborhood (otherwise direct move would work)
                        if c_low in neighbor_colors:
                            continue

                        # Build the Kempe chain component containing v for colors c and c_low
                        # We'll do BFS/DFS on the subgraph induced by colors c and c_low
                        from collections import deque
                        visited = set()
                        queue = deque([v])
                        visited.add(v)
                        component = set()
                        # We want to see if we can swap c and c_low in this component
                        # without causing conflict. Actually, we check if swapping frees color c for v.
                        # Standard: if the component does not contain any neighbor of v colored c_low,
                        # then swapping will move v to c_low and not introduce conflict.
                        has_c_low_neighbor = False
                        while queue:
                            node = queue.popleft()
                            component.add(node)
                            for u in neighbors[node]:
                                if colors[u] == c or colors[u] == c_low:
                                    if u not in visited:
                                        visited.add(u)
                                        queue.append(u)
                                    # Check if this neighbor is colored c_low and adjacent to v
                                    if u == v and colors[u] == c_low:  # self not possible
                                        pass
                                    if u in neighbors[v] and colors[u] == c_low:
                                        has_c_low_neighbor = True

                        # If no neighbor of v in the component is colored c_low, swapping is safe
                        if not has_c_low_neighbor:
                            # Perform swap: c <-> c_low in component
                            for node in component:
                                if colors[node] == c:
                                    colors[node] = c_low
                                elif colors[node] == c_low:
                                    colors[node] = c
                            # Update color classes
                            for node in component:
                                old_c = c if colors[node] == c_low else c_low
                                new_c = colors[node]
                                color_classes[old_c].remove(node)
                                color_classes[new_c].append(node)
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break

            # Update max_color if highest color class is empty
            while max_color >= 0 and not color_classes[max_color]:
                max_color -= 1

        return colors

    # Try multiple algorithms and select the best
    best_colors = None
    best_num_colors = float('inf')

    # List of algorithms to try
    algorithms = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Welsh-Powell", welsh_powell),
        ("Smallest-Last", smallest_last)
    ]

    for name, algo in algorithms:
        try:
            cols = algo()
            # Validate coloring
            valid = True
            for i in range(n):
                for j in neighbors[i]:
                    if i < j and cols[i] == cols[j]:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                num_colors = len(set(cols))
                if num_colors < best_num_colors:
                    best_num_colors = num_colors
                    best_colors = cols[:]
        except Exception:
            continue

    # Fallback: greedy in random order
    if best_colors is None:
        order = list(range(n))
        random.shuffle(order)
        colors = [-1] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        best_colors = colors

    # Apply Kempe refinement to try to reduce further
    try:
        refined = kempe_refine(best_colors)
        # Validate refined coloring
        valid = True
        for i in range(n):
            for j in neighbors[i]:
                if i < j and refined[i] == refined[j]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            num_colors_refined = len(set(refined))
            if num_colors_refined < best_num_colors:
                best_colors = refined
    except Exception:
        pass

    return best_colors
